static void packet_remove_mclist_entries(struct net_device *dev, struct net *net)
{
	struct sock *sk;
	struct sock *batch[16];
	int n_batch;

	do {
		n_batch = 0;
		rcu_read_lock();
		sk_for_each_rcu(sk, &net->packet.sklist) {
			struct packet_sock *po = pkt_sk(sk);
			struct packet_mclist *ml;

			for (ml = po->mclist; ml; ml = ml->next) {
				if (ml->ifindex == dev->ifindex) {
					sock_hold(sk);
					batch[n_batch++] = sk;
					break;
				}
			}
			if (n_batch >= 16)
				break;
		}
		rcu_read_unlock();

		if (n_batch > 0) {
			int i;

			for (i = 0; i < n_batch; i++) {
				packet_dev_mclist_delete(dev, &pkt_sk(batch[i])->mclist);
				sock_put(batch[i]);
			}
		}
	} while (n_batch == 16);
}

